device.kernel:
({
  poly: 8,
  create({ sr, dsp }) {
    return {
      voice(i) {
        const a = dsp.osc('sine'), b = dsp.osc('sine');
        let amp = 0, k = 1, kr = 1, held = false;
        return {
          start(pitch, vel, p) {
            a.freq(dsp.mtof(pitch)).reset(0); b.freq(dsp.mtof(pitch) * 2.76).reset(0);
            amp = 0.3 * vel; held = true;
            k = Math.exp(Math.log(0.001) / (p.ring * sr));        // -60 dB in p.ring seconds
            kr = Math.exp(Math.log(0.001) / (0.15 * sr));         // and in 0.15 s once let go
          },
          release(p) { held = false; },
          render(L, R, n, p) {
            const g = held ? k : kr;
            for (let i = 0; i < n; i++) {
              const y = amp * (0.8 * a.next() + 0.2 * b.next() * amp / 0.3);
              amp *= g; L[i] += y; R[i] += y;
            }
            return amp > 1e-5;
          },
        };
      },
    };
  },
})
